import json

def solve_limited(grid):
    n, m = len(grid), len(grid[0])
    positions = {}
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != 0:
                if val not in positions:
                    positions[val] = []
                positions[val].append((r, c))

    if 1 not in positions or 2 not in positions:
        return grid

    r1, c1 = positions[1][0]
    r2, c2 = positions[2][0]

    result = [[x for x in row] for row in grid]
    ar_sum = r1 + c1
    min_r, max_r = min(r1, r2), max(r1, r2)

    # Anti-diagonal
    for r in range(min_r + 1, max_r):
        c = ar_sum - r
        if 0 <= r < n and 0 <= c < m:
            result[r][c] = 3

    row_horiz = min_r + 1
    anti_col = ar_sum - row_horiz

    test_cols_diff = abs(c1 - c2)
    # Length based on column distance
    if test_cols_diff >= 10:
        length = 4
    elif test_cols_diff >= 8:
        length = 3
    elif test_cols_diff >= 6:
        length = 2
    else:
        length = 1

    # Extend RIGHT from anti_col
    for i in range(length):
        c = anti_col + i
        if 0 <= row_horiz < n and 0 <= c < m:
            result[row_horiz][c] = 3

    return result

