import json

def solve_debug(grid):
    n, m = len(grid), len(grid[0])
    positions = {}
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val != 0:
                if val not in positions:
                    positions[val] = []
                positions[val].append((r, c))

    r1, c1 = positions[1][0]
    r2, c2 = positions[2][0]

    result = [[0]*m for _ in range(n)]
    ar_sum = r1 + c1
    print(f"ar_sum={ar_sum}, r1={r1}, c1={c1}, r2={r2}, c2={c2}")

    min_r, max_r = min(r1, r2), max(r1, r2)
    print(f"min_r={min_r}, max_r={max_r}")
    print(f"Anti-diag range: range({min_r+1}, {max_r}) = {list(range(min_r + 1, max_r))}")

    for r in range(min_r + 1, max_r):
        c = ar_sum - r
        print(f"  r={r}, c={ar_sum-r} from r+c={ar_sum}")
        if 0 <= r < n and 0 <= c < m:
            result[r][c] = 3
        else:
            print(f"    SKIP (out of bounds)")

    row_horiz = min_r + 1
    anti_col = ar_sum - row_horiz
    print(f"Horizontal at row={row_horiz}, anti_col={anti_col}")

    for i in range(3):
        c = anti_col + i
        print(f"  horiz: c={anti_col + {i:0} - 3}")
        if 0 <= row_horiz < n and 0 <= c < m:
            result[row_horiz][c] = 3

    print("Final result:")
    for r in range(n):
        row_str = ' '.join(str(result[r][c]) for c in range(m))
        if '3' in row_str:
            print(f"Row {r}: {row_str}")

    return result

